// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

public class VarEqualityTest {

	private static final Value VALUE = SimpleValueFactory.getInstance().createLiteral("v");

	static class CustomVar extends Var {
		CustomVar(String name, Value value, boolean anonymous, boolean constant) {
			super(name, value, anonymous, constant);
		}
	}

	@Test
	void clonedOccurrenceIsDetachedAndRetainsProvenance() {
		Var v = Var.of("x", VALUE, true, true, true).withApiInputOrigin();
		v.setLegacyGraphContextDepth(3);
		v.setVariableScopeChange(true);
		StatementPattern parent = new StatementPattern(v, Var.of("p"), Var.of("o"));
		Var copy = v.clone();

		assertNotSame(v, copy);
		assertNull(copy.getParentNode());
		assertSame(parent, v.getParentNode());
		assertSame(VALUE, copy.getValue());
		assertTrue(copy.isAnonymous());
		assertTrue(copy.isConstant());
		assertTrue(copy.isBNode());
		assertTrue(copy.isVariableScopeChange());
		assertTrue(copy.hasApiInputOrigin());
		assertEquals(3, copy.getGraphContextDepth());
		assertEquals(v, copy);
		assertEquals(v.hashCode(), copy.hashCode());

		copy.setGraphContextDepth(5);
		copy.setVariableScopeChange(false);
		assertEquals(3, v.getGraphContextDepth());
		assertFalse(copy.isVariableScopeChange());
		assertTrue(v.isVariableScopeChange());
	}

	@Test
	void equalitySupportsCustomProviderSubclass() {
		Var base = Var.of("x", VALUE, false, false);
		Var subclass = new CustomVar("x", VALUE, false, false);

		assertTrue(base.equals(subclass), "base should equal subclass with same data");
		assertTrue(subclass.equals(base), "subclass should equal base with same data");
		assertEquals(base.hashCode(), subclass.hashCode(), "hashCode must remain compatible");
	}
}
